import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Ce1WstT_.js";const v=JSON.parse('{"title":"3. Objectives","description":"","frontmatter":{},"headers":[],"relativePath":"overview/objectives.md","filePath":"overview/objectives.md"}'),i={name:"overview/objectives.md"};function s(n,e,l,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-objectives" tabindex="-1">3. Objectives <a class="header-anchor" href="#_3-objectives" aria-label="Permalink to &quot;3. Objectives&quot;">​</a></h1><p>The primary goal of this project is to provide a unified, transactionally safe, and role-gated platform for wholesale operations.</p><p>The specific objectives achieved are:</p><ul><li><strong>Centralized CRM</strong>: Provide a single directory for Lead/Active/Inactive customers and a historical log of all follow-up interactions.</li><li><strong>Inventory Management</strong>: Maintain a central product catalog with real-time stock balances and low-stock threshold alerts.</li><li><strong>Stock Movement Tracking</strong>: Implement an immutable stock ledger where every inventory change is logged with a direction (IN/OUT), reason, and operator ID.</li><li><strong>Sales Challan Workflow</strong>: Enable sales teams to draft multi-item challans and capture static product snapshots to preserve historical pricing/names.</li><li><strong>Transaction Safety</strong>: Guarantee atomic stock deductions utilizing PostgreSQL pessimistic row-level locking (<code>SELECT FOR NO KEY UPDATE</code>) to prevent negative stock under concurrent loads.</li><li><strong>Role-Based Access Control (RBAC)</strong>: Secure routes and API methods strictly across ADMIN, SALES, WAREHOUSE, and ACCOUNTS roles.</li><li><strong>Secure Authentication</strong>: Provide stateless, JWT-driven custom authentication avoiding external auth-provider locks.</li><li><strong>PostgreSQL Database</strong>: Use a strictly relational 3NF database schema backed by Supabase.</li><li><strong>REST API</strong>: Develop a decoupled, robust Node.js + Express backend service validating all input with Zod.</li><li><strong>Responsive Frontend</strong>: Deliver a fast, modern React + TypeScript single-page application (SPA).</li><li><strong>Production Deployment</strong>: Ensure the system is fully prepared for cloud deployment (Vercel + Render/Railway).</li></ul>',4)])])}const u=t(i,[["render",s]]);export{v as __pageData,u as default};
